@router.get("/payments/search")
async def search_payment_records(
    q: Annotated[str | None, Query(min_length=1)] = None,
    payment_status: Annotated[str | None, Query(alias="status", min_length=1)] = None,
    x_merchant_id: Annotated[str | None, Header(alias="X-Merchant-Id")] = None,
    page: Annotated[int, Query(ge=1)] = 1,
    size: Annotated[int, Query(ge=1, le=100)] = 25,
    es: AsyncElasticsearch = Depends(get_es),
):
    return await search_payments(
        es=es,
        query_text=q,
        status=payment_status,
        merchant_id=x_merchant_id,
        page=page,
        size=size,
    )


# ─────────────────────────────────────────────────────────────────────────────
# GET PAYMENT
# ─────────────────────────────────────────────────────────────────────────────

@router.get("/payments/{payment_id}")
async def get_payment(
    payment_id: str,
    x_merchant_id: Annotated[str | None, Header(alias="X-Merchant-Id")] = None,
    db: Session = Depends(get_db),
):
    query = db.query(Payment).filter(Payment.id == payment_id)
    if x_merchant_id:
        query = query.filter(Payment.merchant_id == x_merchant_id)
    payment = query.first()

    if not payment:
        raise HTTPException(status_code=404, detail="Payment not found")

    return build_payment_response(payment)


# ─────────────────────────────────────────────────────────────────────────────
# LIST PAYMENTS
# ─────────────────────────────────────────────────────────────────────────────

@router.get("/payments")
async def list_payments(
    x_merchant_id: Annotated[str | None, Header(alias="X-Merchant-Id")] = None,
    status: str | None = None,
    limit: Annotated[int, Query(ge=1, le=100)] = 10,
    offset: Annotated[int, Query(ge=0)] = 0,
    db: Session = Depends(get_db),
):
    query = db.query(Payment)
    if x_merchant_id:
        query = query.filter(Payment.merchant_id == x_merchant_id)
    if status:
        query = query.filter(Payment.status == status)

    total    = query.count()
    payments = query.order_by(Payment.created_at.desc()).limit(limit).offset(offset).all()

    return {
        "data":     [build_payment_response(p) for p in payments],
        "has_more": (offset + limit) < total,
        "total":    total,
    }
